PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?iri ?title ?status WHERE {
  ?iri rdf:type ?type ; rdfs:label ?title .
  OPTIONAL { ?iri <https://moosedev.dev/kg/ontology/software-architecture/status> ?status }
  FILTER(CONTAINS(LCASE(STR(?type)), "lesson"))
}
ORDER BY LCASE(STR(?title))

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?iri ?title ?status WHERE {
  ?iri rdf:type ?type ; rdfs:label ?title .
  OPTIONAL { ?iri <https://moosedev.dev/kg/ontology/software-architecture/status> ?status }
  FILTER(CONTAINS(LCASE(STR(?type)), "lesson"))
